INSERT INTO "preguntas" ("id","usuario_id","categoria_id","titulo","contenido","imagenes","fecha","votos") VALUES(3,9,'consultas','¿Las actualizaciones borran mis presupuestos?','Cuando salga una versión nueva, ¿pierdo mis presupuestos, precios o fórmulas?',NULL,'2026-09-14 11:57:24',0);
