INSERT INTO "preguntas" ("id","usuario_id","categoria_id","titulo","contenido","imagenes","fecha","votos") VALUES(8,9,'cotizador','Elegir rodamiento o cierre según la abertura','Según el peso de la hoja uso rodamiento simple o doble, y según la abertura cambia el cierre. ¿Tengo que armar un kit para cada caso?',NULL,'2026-09-14 11:57:34',0);
INSERT INTO "preguntas" ("id","usuario_id","categoria_id","titulo","contenido","imagenes","fecha","votos") VALUES(9,9,'cotizador','¿El programa optimiza el corte de vidrio en planchas?','¿El programa me dice cómo cortar los paños de vidrio de las planchas?',NULL,'2026-09-14 11:57:36',0);
