INSERT INTO "preguntas" ("id","usuario_id","categoria_id","titulo","contenido","imagenes","fecha","votos") VALUES(11,9,'calculos','El costo del aluminio me da cero','Cargo una abertura y el costo del aluminio da cero. ¿Qué falta?',NULL,'2026-09-14 11:57:40',0);
